import{_ as e,H as s,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"35 | RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？","description":"","frontmatter":{},"headers":[{"level":2,"title":"NRM 的功能特性","slug":"nrm-的功能特性","link":"#nrm-的功能特性","children":[]},{"level":2,"title":"NRM 的优势","slug":"nrm-的优势","link":"#nrm-的优势","children":[]},{"level":2,"title":"RTMP 协议","slug":"rtmp-协议","link":"#rtmp-协议","children":[]},{"level":2,"title":"HLS 直播协议","slug":"hls-直播协议","link":"#hls-直播协议","children":[]},{"level":2,"title":"项目实战","slug":"项目实战","link":"#项目实战","children":[{"level":3,"title":"Nginx-rtmp-module 配置安装","slug":"nginx-rtmp-module-配置安装","link":"#nginx-rtmp-module-配置安装","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Python实战·从0到1搭建直播视频平台/35｜RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？.md","filePath":"Python实战·从0到1搭建直播视频平台/35｜RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？.md","lastUpdated":1795533265000}'),i={name:"Python实战·从0到1搭建直播视频平台/35｜RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？.md"};function p(l,n,o,E,r,h){return s(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="_35-rtmp协议与nrm搭建-如何使用nrm支持hls协议直播" tabindex="-1">35 | RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？ <a class="header-anchor" href="#_35-rtmp协议与nrm搭建-如何使用nrm支持hls协议直播" aria-label="Permalink to &quot;35 | RTMP协议与NRM搭建：如何使用NRM支持HLS协议直播？&quot;">​</a></h1><p>你好，我是 Barry。</p><p>在上节课我们学习了如何使用 Nginx 来搭建服务器，并完成了防火墙的配置。这节课我们继续来完成直播系统的开发，学习如何通过 NRM 简单迅速地搭建流媒体服务器，并使用 NRM 来支持 HLS 协议直播。</p><p>在动手实操之前，我会先带你认识一下 NRM，之后再为你讲解 RTMP 协议和 HLS 直播协议的工作原理。有了这些理论基础，后面搭建流媒体服务器的时候，你的思路也会更清晰。</p><h2 id="nrm-的功能特性" tabindex="-1">NRM 的功能特性 <a class="header-anchor" href="#nrm-的功能特性" aria-label="Permalink to &quot;NRM 的功能特性&quot;">​</a></h2><p>NRM 实际是 Nginx-rtmp-module 的缩写。这是一个用于 Nginx 的 RTMP 模块，它允许 Nginx作为 RTMP 协议的服务器，主要用来处理基于 RTMP 协议的音频和视频流传输。</p><p>NRM 是 Nginx 的第三方模块，它的开发由第三方开发者研发维护。NRM 模块一直在不断更新和发展，目前已经有大量的开发者为其贡献代码。这是 NRM 的GitHub 地址，你可以课后再花点时间详细了解一下。</p><p>在直播领域里 NRM 应用很广泛。它可以作为直播服务器的后端，接收和处理来自客户端的直播请求，并将直播流传输到其他服务器或客户端上。同时，它还可以与其他直播相关的服务（如 CDN 服务、推流服务器等）集成，提供完整的直播解决方案。</p><p>为了帮你熟练地应用 NRM，我们还需要了解它的功能特点，我们可以从直播流管理、直播流分发、负载均衡、安全性和可定制性这五个方面来把握。具体你可以参考后面的表格。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/1.png" alt=""></a></p><h2 id="nrm-的优势" tabindex="-1">NRM 的优势 <a class="header-anchor" href="#nrm-的优势" aria-label="Permalink to &quot;NRM 的优势&quot;">​</a></h2><p>在了解了功能特性之后，我们再进一步了解一下 NRM 的优势，这样你会更加明确我们为什么选择它来搭建流媒体服务器。</p><p>在直播和点播支持方面，Nginx-rtmp-module 可以作为 RTMP 协议的服务器，接收和处理RTMP 直播请求，并将直播流传输到其他服务器或客户端上。同时，它还支持 HLS 点播，可以将直播流转换为 HLS 流，这样我们就能实现在支持 HLS 协议的客户端上直播。</p><p>另外，Nginx-rtmp-module 还支持将一次直播流分为多个视频文件存储，以便后续的处理和分析。这可以用于实现直播内容的分段存储、录制和回放等功能，也有助于我们分析直播数据，优化产品。</p><p>在音视频解码方面，Nginx-rtmp-module 可以支持 H.264 视频编解码器和 AAC 音频编解码器。这能保障直播过程中的音视频质量，并提供高效的编解码处理。Nginx-rtmp-module 还支持回调 HTTP，作用是完成直播里的 HTTP 请求和响应操作。这个功能可以帮我们实现直播模块和后端系统的通信、请求和响应等功能。</p><p>在直播系统中，我们可以使用 HTTP 控制直播。通过发送 HTTP 请求到 Nginx-rtmp-module，我们能给用户提供更完善的直播管理功能，比如直播的开启、停止、删除、录播保存等等。</p><p>同时，Nginx-rtmp-module 具备更优秀的缓存技术，可以在效率和解码之间达到平衡，获得更好的缓存效果。这样模块在处理大量直播流时，仍然可以保持高性能状态，实现低延迟且稳定的流传输。</p><h2 id="rtmp-协议" tabindex="-1">RTMP 协议 <a class="header-anchor" href="#rtmp-协议" aria-label="Permalink to &quot;RTMP 协议&quot;">​</a></h2><p>前面我们说过 NRM 是处理基于 RTMP 协议的音频和视频流传输，那 RTMP 协议在直播里又起到了什么作用呢？我们这就来看看。</p><p>RTMP（Real-Time Messaging Protocol）是一种实时消息传输协议。它是一种基于网络的应用层协议，用来在客户端和服务器之间传输实时音频、视频和数据。</p><p>2005 年，当时 Adobe Systems 为了实现 Flash 播放器与服务器之间的实时通信而推出了RTMP 协议。随着 Flash 播放器越来越普及，RTMP 协议得到了广泛应用。后来，HTML5 技术逐渐发展起来，Adobe Systems 也在 2011 年推出了支持 HTML5 的 RTMP 协议实现，即RTMP 协议的变形版本——RTMP-c。</p><p>RTMP-c 的实时性较强，延迟在 1-2s 内。RTMP 适用于多种应用场景，如直播、视频播放、数据传输、实时通信等，你可以参考我整理的表格。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/2.png" alt=""></a></p><p>接下来，我带你梳理一下 RTMP 协议的客户端和服务端建立连接流程，也就是 RTMP 协议握手的过程。</p><p>在 RTMP 协议中，握手过程由三个固定大小的 chunk 组成，而不是像其他协议一样由可变大小的带有头文件的 chunk 组成。这三个 chunk 分别是 C0、S0 和 C1。</p><ul><li><p>C0：客户端发送的 RTMP 协议连接请求</p></li><li><p>S0：服务器发送的 RTMP 协议连接响应</p></li><li><p>C1：客户端发送的确认消息</p></li></ul><p>在 RTMP 协议中，这三个 chunk 的大小是固定的，而且不包含头文件。这种握手方式相对简单，但是可以确保握手过程稳定可靠。</p><p>整个握手过程可以拆解为三步，我们分别来看看每一步具体执行了什么动作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/3.jpeg" alt=""></a></p><p>第一步，客户端发送一个 RTMP 请求连接消息（C0/C1）给服务器，其中包含用于建立连接的参数，如 IP 地址、端口号和协议版本等。</p><p>第二步，服务器收到请求后，发送一个确认连接消息（S0/S1）给客户端，表示服务器已经接受连接请求。</p><p>第三步，客户端再发送一个确认消息（C2）给服务器，表示客户端已经接受服务器的确认，连接建立成功。等服务器收到（C2）消息之后，会发送一个（S2）消息给客户端，确认连接已经建立，并通知客户端可以开始传输数据。</p><p>以上每一步的执行，服务器和客户端都需要等到确切的反馈结果，才会执行下一次的交互发送，比如客户端要在等收到 S1 之后，才能向服务端发送 C2。在整个握手过程中，为了保证客户端和服务器成功建立链接，提升链接的安全性和可靠性，RTMP 协议还进行了一些安全验证和加密操作。</p><p>搭建直播系统时，我们需要根据具体的应用场景和需求来选择适合的协议，或者将多个协议进行整合使用，以满足不同的需求。</p><h2 id="hls-直播协议" tabindex="-1">HLS 直播协议 <a class="header-anchor" href="#hls-直播协议" aria-label="Permalink to &quot;HLS 直播协议&quot;">​</a></h2><p>除了 RTMP 协议，还有一个协议在直播领域应用也很广泛，它就是 HLS 直播协议。</p><p>HLS（HTTP Live Streaming）是一种基于 HTTP 协议的流媒体传输协议，适用于直播、视频播放和实时通信等场景。在 2009 年，苹果公司推出了 HLS 协议，主要用于在移动设备上实现流媒体传输。</p><p>HLS 协议能够将直播流分割为多个小的 HTTP 文件，通过 TCP 协议进行传输。这种传输方式可以适应不同的网络状况，实现更加稳定和可靠的流媒体传输。另外，为满足不同应用场景的需求，HLS 协议还支持多种音视频编码格式（如 AAC、H.264 等）。HLS 协议的适用场景，你同样可以参考后面的表格。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/4.png" alt=""></a></p><p>不难发现，HLS 直播协议的优势在于强大的低延迟、多编码格式、分布式直播等能力，还有它可以支持移动端直播。</p><p>提到 HLS 直播协议，就不得不说一说 M3U8 文件。在 HLS 直播协议的应用中，需要使用M3U8 文件来描述直播流的元数据信息。</p><p>M3U8 文件是一个文本文件，它包含多个媒体文件的 URL 地址，以及一些其他的元数据信息，如编码格式、分辨率等。</p><p>在 HLS 直播中，服务器会定期发送 M3U8 文件给客户端，客户端通过解析 M3U8 文件，可以获取到当前直播流的元数据信息，以及最新的媒体文件列表。这样，播放器就可以根据这些信息选择合适的媒体文件进行播放，直播也会更加流畅稳定。</p><h2 id="项目实战" tabindex="-1">项目实战 <a class="header-anchor" href="#项目实战" aria-label="Permalink to &quot;项目实战&quot;">​</a></h2><p>接下来，我们结合前面所学，一起完成 NRM 的搭建，并通过配置实现支持 HLS 协议直播。</p><h3 id="nginx-rtmp-module-配置安装" tabindex="-1">Nginx-rtmp-module 配置安装 <a class="header-anchor" href="#nginx-rtmp-module-配置安装" aria-label="Permalink to &quot;Nginx-rtmp-module 配置安装&quot;">​</a></h3><p>首先，我们需要先下载 Nginx-rtmp-module。从官方的 Git 地址把 NRM 克隆下来，拉取并下载到 Linux 中。具体的执行命令如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/arut/nginx-rtmp-module.git</span></span></code></pre></div><p>当然你还可以选择另一种下载方式：在 GitHub 中打开 Nginx-rtmp-module 的首页，点击“code”，在下拉菜单选择 “Download.zip” 下载压缩包，即可直接完成下载，然后把它放到我们自己的服务器里。后面是操作截图，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/5.png" alt=""></a></p><p>当然，你也可以使用 wget 命令下载并解压。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/arut/nginx-rtmp-module/archive/master.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  master.zip</span></span></code></pre></div><p>第 1 行命令的含义是使用 wget 工具，从 GitHub 上下载 nginx-rtmp-module 的 master 分支代码，并将其保存为 master.zip 文件。紧接着我们通过 unzip 工具将 master.zip 文件解压缩到当前目录下。</p><p>接下来，就到了编译安装 Nginx-rtmp-module 的环节，我们就要进入 Nginx 解压目录，执行configure。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./configure --add-module=../nginx-rtmp-module-master</span></span>
<span class="line"><span>make</span></span>
<span class="line"><span>make install</span></span></code></pre></div><p>第 1 行命令.configure 用于配置 nginx 的编译环境，其中–add-module 参数指定了要添加的Nginx-rtmp-module 的路径，命令中的…/nginx-rtmp-module-master 就是指添加到 nginx 的编译环境中，这个地址你可以自己选择。</p><p>第 2 行命令 make 的作用是编译 nginx，它会根据配置文件和源代码文件自动生成可执行文件。再看第三行命令，make install 用于将编译好的可执行文件复制到指定的安装目录中，并将相关的配置文件和模块文件也复制到相应的位置。</p><p>因为 Nginx 默认是不支持 rtmp，所以我们还需要修改配置文件。你只需要进入 bin/conf 目录，找到 nginx.conf 文件，然后在配置文件中添加后面的配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rtmp {</span></span>
<span class="line"><span>   server {</span></span>
<span class="line"><span>       listen 1935;</span></span>
<span class="line"><span>       #应用程序块</span></span>
<span class="line"><span>       application mylive {</span></span>
<span class="line"><span>           live on;</span></span>
<span class="line"><span>           hls on;</span></span>
<span class="line"><span>           hls_path /usr/local/m3u8File;</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>因为配置文件涉及到的配置项比较多，为了方便你学习，我直接整理成了表格。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/6.png" alt=""></a></p><p>因为 HLS 协议是基于 HTTP 协议的，所以无法通过 RTMP 协议头访问 HLS 的 M3U8 文件。为了配置对 HLS 的访问操作，我们还要完成一个关键操作——修改 http 中的 server 模块。</p><p>你需要加入的就是 location 的部分，具体的配置项是后面这样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>   listen 80;</span></span>
<span class="line"><span>   location /mylive_hls {</span></span>
<span class="line"><span>       types {</span></span>
<span class="line"><span>           application/vnd.apple.mpegurl m3u8;</span></span>
<span class="line"><span>           video/mp2t ts;</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>       alias /usr/local/m3u8File;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>你可以看看配置内容，核心配置项的解释如下表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/7.png" alt=""></a></p><p>完成前面的配置后，我们就可以启动 Nginx 了，别忘了指定 Nginx 服务器的可执行文件路径，这样才能让对应的配置生效。具体的命令如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/usr/local/nginx/sbin/nginx -c /usr/local/nginx/conf/nginx.conf</span></span></code></pre></div><p>然后我们查看 Nginx 的进程，如果出现后面截图里的执行效果，这就代表服务启动成功了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/35/8.png" alt=""></a></p><p>到这里，我们就安装搭建好了 Nginx-rtmp-module，还用它支持了 HLS 协议直播。下节课我们继续学习如何实现推拉流，让直播动起来，敬请期待。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>又到了课程的尾声，我们一起回顾总结一下这节课的内容。</p><p>Nginx-rtmp-module 是一个用于 Nginx 的 RTMP 模块，它允许 Nginx 作为 RTMP 协议的服务器。综合来看，Nginx-rtmp-module 可以满足不同应用场景的需求，并提供高效、稳定的RTMP 和 HLS 直播服务，非常适合应用在我们的直播系统中。</p><p>RTMP 协议是一种用于实时音视频和数据传输的协议，适用于多种应用场景，如直播、视频播放、数据传输、实时通信等。而 HLS 协议是一种基于 HTTP 协议的流媒体传输协议，适用于移动设备上的直播应用，可以适应不同的网络状况，实现稳定可靠的流媒体传输。</p><p>在项目实战部分，我们一起完成了 Nginx-rtmp-module 的安装配置，这一部分的操作步骤我写得比较详细。另外，因为 HLS 协议是基于 HTTP 协议的，无法通过 RTMP 协议头访问 HLS的 M3U8 文件，所以我们需要修改 http 中的 server 模块。</p><p>实战部分还有配置文件中的参数，建议你课后多花一些时间理解和掌握，这样才能真正把这些知识化为己用。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在直播系统中，直播传输除了 M3U8 类型文件外，你还知道哪几种常见的文件类型？</p><p>欢迎你在留言区和我交流互动，也推荐你把这节课分享给身边更多朋友。</p>`,80)])])}const c=e(i,[["render",p]]);export{g as __pageData,c as default};
